# Try rotating and flipping combinations
def rotate(grid, times=1):
    result = grid[:]
    for _ in range(times % 4):
        result = [[result[r][c] for r in range(len(result))] for c in range(len(result[0]))]
        result = list(zip(*result[::-1]))  # transpose + reverse
    return [list(row) for row in result]

def flip_h(grid):
    return [row[::-1] for row in grid]

def flip_v(grid):
    return grid[::-1]

original = input_pattern
for i, name in enumerate(["", "H_flip", "V_flip", "flip_H+V", "90°", "180°", "270°"]):
    g = original.copy()
    if 'H' in name:
        g = flip_h(g)
    if 'V' in name:
        g = flip_v(g)
    if '90' in name:
        g = rotate(g, 1)
    if '180' in name:
        g = rotate(g, 2)
    if '270' in name:
        g = rotate(g, 3)

    # Also consider flipped versions of rotated
    hflipped = flip_h(g)

