def expand_and_mirror(grid):
    h, w = len(grid), len(grid[0])

    # Scale each cell to 2x2
    scaled = [[None]*(2*w) for _ in range(2*h)]
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            scaled[r*2][c*2] = scaled[r*2][c*2+1] = scaled[r*2+1][c*2] = scaled[r*2+1][c*2+1] = val

    # Mirror horizontally
    for r in range(2*h):
        for c in range(w):
            scaled[r][2*w - 1 - c] = scaled[r][c]

    # Mirror vertically
    for r in range(h):
        for c in range(2*w):
            scaled[2*h - 1 - r][c] = scaled[r][c]

    return scaled

