def expand_and_mirror_4way(grid):
    """Expand 2x then mirror horizontally and vertically around center"""
    h, w = len(grid), len(grid[0])

    # Start with expanded content in top-left corner
    canvas = [[None]*(w*2) for _ in range(h*2)]

